def list_all_users(limit=None, cursor=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0213000" if __import__("os").path.isdir("./environment_mix/0213000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    # Strict validation
    if limit is not None:
        if not isinstance(limit, int):
            return _err("VALIDATION_ERROR", "limit must be an integer", field="limit")
        if limit < 1:
            return _err("VALIDATION_ERROR", "limit must be at least 1", field="limit", minimum=1)
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string", field="cursor")

    # Rate limiting / logging (create audit collection if absent)
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    audit_file = "request_log.json"
    logs = _load(audit_file)
    if not isinstance(logs, list):
        logs = []

    # Simple rolling window rate limit: 300 requests / 60 seconds
    window_seconds = 60
    limit_per_window = 300
    cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=window_seconds)
    recent = 0
    for r in logs[-2000:]:
        ts = r.get("timestamp")
        if isinstance(ts, str):
            try:
                if ts.endswith("Z"):
                    dt = datetime.datetime.fromisoformat(ts[:-1])
                else:
                    dt = datetime.datetime.fromisoformat(ts)
                if dt >= cutoff:
                    recent += 1
            except Exception:
                pass
    if recent >= limit_per_window:
        latency_ms = int((time.time() - t0) * 1000)
        logs.append({
            "id": "req-" + uuid.uuid4().hex[:24],
            "endpoint": "list_all_users",
            "timestamp": now,
            "status": "RATE_LIMIT",
            "latency_ms": latency_ms,
            "credential": None
        })
        _save(audit_file, logs)
        return _err("RATE_LIMIT", "Too many requests")

    users = _load("users.json")
    if not isinstance(users, list):
        users = []

    # Deterministic ordering for pagination
    users_sorted = sorted(users, key=lambda r: (str(r.get("id", "")), str(r.get("email", ""))))

    start = 0
    if cursor:
        # Cursor format: "idx:<int>"
        if cursor.startswith("idx:"):
            try:
                start = int(cursor.split(":", 1)[1])
            except Exception:
                return _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")
        else:
            return _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")

        if start < 0 or start > len(users_sorted):
            return _err("VALIDATION_ERROR", "cursor is out of range", field="cursor")

    page_size = limit if limit is not None else 100
    end = min(start + page_size, len(users_sorted))
    data = users_sorted[start:end]

    has_more = end < len(users_sorted)
    next_cursor = f"idx:{end}" if has_more else None

    latency_ms = int((time.time() - t0) * 1000)
    logs.append({
        "id": "req-" + uuid.uuid4().hex[:24],
        "endpoint": "list_all_users",
        "timestamp": now,
        "status": "OK",
        "latency_ms": latency_ms,
        "credential": None,
        "meta": {"returned": len(data), "total": len(users_sorted)}
    })
    _save(audit_file, logs)

    return {
        "object": "list",
        "data": data,
        "limit": page_size,
        "cursor": cursor,
        "next_cursor": next_cursor,
        "has_more": has_more,
        "total": len(users_sorted)
    }

