def list_events_in_range(start_date, end_date, **_extra):
    import json, os, datetime, time, uuid, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0213000" if __import__("os").path.isdir("./environment_mix/0213000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    if not isinstance(start_date, str):
        return _err("VALIDATION_ERROR", "start_date must be a string in YYYY-MM-DD", field="start_date")
    if not isinstance(end_date, str):
        return _err("VALIDATION_ERROR", "end_date must be a string in YYYY-MM-DD", field="end_date")

    if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", start_date or ""):
        return _err("VALIDATION_ERROR", "start_date must be in YYYY-MM-DD form", field="start_date")
    if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", end_date or ""):
        return _err("VALIDATION_ERROR", "end_date must be in YYYY-MM-DD form", field="end_date")

    try:
        s = datetime.date.fromisoformat(start_date)
        e = datetime.date.fromisoformat(end_date)
    except Exception:
        return _err("VALIDATION_ERROR", "Invalid date value", field="date")

    if e < s:
        return _err("VALIDATION_ERROR", "Invalid range: end_date is earlier than start_date", field="end_date")

    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    audit_file = "request_log.json"
    logs = _load(audit_file)
    if not isinstance(logs, list):
        logs = []

    window_seconds = 60
    limit_per_window = 300
    cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=window_seconds)
    recent = 0
    for r in logs[-2000:]:
        ts = r.get("timestamp")
        if isinstance(ts, str):
            try:
                dt = datetime.datetime.fromisoformat(ts[:-1]) if ts.endswith("Z") else datetime.datetime.fromisoformat(ts)
                if dt >= cutoff:
                    recent += 1
            except Exception:
                pass
    if recent >= limit_per_window:
        latency_ms = int((time.time() - t0) * 1000)
        logs.append({
            "id": "req-" + uuid.uuid4().hex[:24],
            "endpoint": "list_events_in_range",
            "timestamp": now,
            "status": "RATE_LIMIT",
            "latency_ms": latency_ms,
            "credential": None
        })
        _save(audit_file, logs)
        return _err("RATE_LIMIT", "Too many requests")

    events = _load("events.json")
    if not isinstance(events, list):
        events = []

    def _event_start_date(ev):
        st = ev.get("start_time")
        if not isinstance(st, str):
            return None
        # Accept "...Z" and offsets and naive timestamps
        try:
            if st.endswith("Z"):
                dt = datetime.datetime.fromisoformat(st[:-1] + "+00:00")
            else:
                dt = datetime.datetime.fromisoformat(st)
            return dt.date()
        except Exception:
            # Try extracting YYYY-MM-DD prefix if present
            try:
                if len(st) >= 10 and re.fullmatch(r"\d{4}-\d{2}-\d{2}", st[:10]):
                    return datetime.date.fromisoformat(st[:10])
            except Exception:
                return None
        return None

    out = []
    for ev in events:
        d = _event_start_date(ev)
        if d is not None and s <= d <= e:
            out.append(ev)

    out = sorted(out, key=lambda r: (str(r.get("start_time", "")), str(r.get("event_id", ""))))

    latency_ms = int((time.time() - t0) * 1000)
    logs.append({
        "id": "req-" + uuid.uuid4().hex[:24],
        "endpoint": "list_events_in_range",
        "timestamp": now,
        "status": "OK",
        "latency_ms": latency_ms,
        "credential": None,
        "meta": {"returned": len(out), "start_date": start_date, "end_date": end_date}
    })
    _save(audit_file, logs)

    return {"object": "list", "data": out, "total": len(out)}

