        users = []

    known = False
    email_l = email.lower()
    for u in users:
        em = u.get("email")
        if isinstance(em, str) and em.lower() == email_l:
            known = True
            break
    if not known:
        latency_ms = int((time.time() - t0) * 1000)
        logs.append({
            "id": "req-" + uuid.uuid4().hex[:24],
            "endpoint": "list_user_events_on_date",
            "timestamp": now,
            "status": "NOT_FOUND",
            "latency_ms": latency_ms,
            "credential": None,
            "meta": {"user_email": email, "date": date}
        })
        _save(audit_file, logs)
        return _err("NOT_FOUND", "user_email does not belong to a known user", user_email=email)

